					}
					cfg, err := Load()
					if err != nil {
						t.Fatalf("load: %v", err)
					}
					if got := setting.get(cfg); got != tc.want {
						t.Fatalf("%s=%q: got %s, want %s", key, tc.value, got, tc.want)
					}
				})
			}
		})
	}
}

